input signed [ENCODER_COUNTER_WIDTH-1:0] enc_count;
input signed [HALL_COUNTER_WIDTH-1:0] hall_count;
output reg fault = 0;


wire low_enc_count   = ( enc_count  < 2 ) & ( enc_count >  -2 );
wire high_hall_count = ( hall_count > 2 ) | ( hall_count < -2 );


