    data1 = 8'h00;
    data2 = 8'h00;
end

// Check if bit 1 is set
always @(*) begin
    data1 = 8'h00;  // Reset data1 before checking
    if (decode_vec[1]) begin
        data1 = 8'h55;
    end
end

// Check if bit 2 is set
always @(*) begin
    data2 = 8'h00;  // Reset data2 before checking
    if (decode_vec[2]) begin
        data2 = 8'h55;
    end
end

