description:
Design a 13-bit Linear Feedback Shift Register (LFSR) that generates pseudo-random numbers with each clock cycle. The LFSR shifts its bits while using a feedback mechanism based on a combination of specific bits to produce new outputs, resetting to an initial value when a reset signal is asserted. It counts up to 13 clock cycles, at which point it captures the current random output for external access. The final output `rnd` provides the random number generated by the LFSR.
module top_module(
    input clock,
    input reset,
    output [12:0] rnd 
    );

code:
module top_module(
    input clock,
    input reset,
    output [12:0] rnd 
    );wire feedback = random[12] ^ random[3] ^ random[2] ^ random[0]; 

reg [12:0] random, random_next, random_done;
reg [3:0] count, count_next; 

always @ (posedge clock or posedge reset)
begin
 if (reset)
 begin
  random <= 13'hF; 
  count <= 0;
 end

 else
 begin
  random <= random_next;
  count <= count_next;
 end
end

always @ (*)
begin
 random_next = random; 
 count_next = count;

  random_next = {random[11:0], feedback}; 
  count_next = count + 1;

 if (count == 13)
 begin
  count = 0;
  random_done = random; 
 end

end


assign rnd = random_done;

endmodule

