	assign O[6:0] = {1'b1,1'b0,1'b0,1'b0,1'b0,1'b0,1'b0};
	assign BLANK[6:0] = {1'b1,1'b1,1'b1,1'b1,1'b1,1'b1,1'b1};

	always@(C)
		case(C)
			3'b000 : OUT = H;
			3'b001 : OUT = E;
			3'b010 : OUT = L;
			3'b011 : OUT = O;
			default : OUT = BLANK;
	endcase	
