description:
Design a control unit that manages a three-cycle process based on an enable signal, clock, and reset. The module features an output signal, enable_DP, which activates after two cycles when the enable input is asserted, transitioning it to HIGH, and then resets to LOW otherwise. The internal state, represented by a 3-bit counter, increments with each clock cycle when enable is HIGH and wraps back to the beginning after reaching the specified end cycle. A reset condition clears the counter and ensures the output remains disabled.
module top_module(
  output reg	enable_DP,
  input		enable, clk, rst
);

code:
module top_module(
  output reg	enable_DP,
  input		enable, clk, rst
);reg [2:0] cylces;
parameter BeginCycle=0, EndCycle=2;

  always @(posedge clk)
    if (rst == 1) enable_DP <=0;
	 else if (cylces==EndCycle) enable_DP<=1;
	 else enable_DP<=0;

always@(posedge clk)
	if (rst==1) cylces<=0;
	else 
	case (enable)
	0: cylces<=cylces;
	1: if(cylces<EndCycle) cylces<=cylces+1;
	else cylces<=BeginCycle;
	endcase

endmodule

