        .time_ptp_sec(time_ptp_sec),
        .time_reg_ns(time_reg_ns),
        .time_reg_sec(time_reg_sec)
    );

    // Clock generation (10ns period)
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

    task reset_dut;
    //define reset task
    endtask
    // Test stimulus
    initial begin
        // Initialize
        test_num = 0;
        pass_count = 0;
        fail_count = 0;

        $display("========================================");
        $display("rtc Testbench");
        $display("========================================");




// Print summary
